insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('6c4dd02a-f19e-57b9-8431-fce21cb4e775', 'cirurgia_plastica', 'Cirurgia Plástica, Procedimentos Estéticos e Dano Estético', 'Avaliação médico-pericial de cirurgia plástica e procedimentos estéticos: análise da indicação, consentimento, ato operatório, evolução pós-operatória, distinção entre complicação e falha técnica, consolidação médico-legal, nexo causal, danos temporários e permanentes, e valoração individualizada do dano estético (escala PERICONS de 7 graus e método AIPE/Brasil como apoio).', 6, true);
